// utils/api.js
const API_BASE_URL = "https://script.google.com/macros/s/AKfycbxr3i-jsk4zc1LiL00wtUSucvmce6E8nEblhS8NHA9a1bQlwEOcI13MQhC7RPZGjxfQ/exec";

export const USER_ROLES = {
  admin: { name: "Admin", canActivate: true, canSeeCommission: true },
  manager: { name: "Manager", canActivate: false, canSeeCommission: false }
};

export const DEMO_USERS = {
  admin: { password: "wangai", role: "admin" },
  manager: { password: "manager123", role: "manager" }
};

export const apiCall = async (action, params = {}) => {
  let url = `${API_BASE_URL}?action=${action}`;
  Object.keys(params).forEach(key => {
    if (params[key] !== undefined && params[key] !== null && params[key] !== "") {
      url += `&${encodeURIComponent(key)}=${encodeURIComponent(params[key])}`;
    }
  });
  
  try {
    const response = await fetch(url, { method: 'GET', headers: { 'Accept': 'application/json' } });
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    const data = await response.json();
    return data;
  } catch (err) {
    console.error("API Error:", err);
    return { success: false, error: err.message };
  }
};

export const escapeHtml = (str) => {
  if (str === undefined || str === null) return "";
  return String(str).replace(/[&<>]/g, function(m) {
    if (m === '&') return '&amp;';
    if (m === '<') return '&lt;';
    if (m === '>') return '&gt;';
    return m;
  });
};

export const normalizePhone = (phone) => {
  if (!phone) return "";
  let normalized = String(phone).replace(/\D/g, '');
  if (normalized.startsWith('254')) {
    normalized = normalized.substring(3);
  } else if (normalized.startsWith('0')) {
    normalized = normalized.substring(1);
  }
  return normalized;
};

export const hasActivationAccess = (role) => {
  return USER_ROLES[role]?.canActivate !== false;
};

export const canSeeCommission = (role) => {
  return USER_ROLES[role]?.canSeeCommission !== false;
};
